-- Return a corrected COPY only for a known extraction. Explicit restore runs
-- restore original white artwork alpha; they never synthesize RGB values. Any different byte,
-- including a semitransparent edge or authored color, rejects the whole mask.
function Cutouts.repairData(data, species)
  if not speciesWithRules[species] then return nil end
  if not (data and data.getDimensions and data.getString and data.clone
      and love.data and love.data.hash and love.data.encode) then return nil end
  local width, height = data:getDimensions()
  if (width ~= 40 and width ~= 48 and width ~= 56) or height ~= width then return nil end
  if data.getFormat and data:getFormat() ~= "rgba8" then return nil end
  local bytes = data:getString()
  if #bytes ~= width * height * 4 then return nil end
  local digest = love.data.encode("string", "hex", love.data.hash("sha256", bytes))
  local rule = rules[digest]
  if not rule or rule.species ~= species
      or rule.width ~= width or rule.height ~= height then return nil end
  local out = data:clone()
  for _, run in ipairs(rule.runs) do
    for x = run[2], run[3] do
      local r, g, b = out:getPixel(x, run[1])
      out:setPixel(x, run[1], r, g, b, 0)
    end
  end
  for _, run in ipairs(rule.restore_runs or {}) do
    for x = run[2], run[3] do
      local r, g, b = out:getPixel(x, run[1])
      out:setPixel(x, run[1], r, g, b, 1)
    end
  end
  return out, rule.count, rule.restore_count or 0
end

local cache = setmetatable({}, { __mode = "k" })
-- Assets invalidation creates new source Image identities, hence new entries.
-- Keep a still-open native screen's old Image paired with its old cutout;
-- weak keys release both once that screen/cache drops the source.

-- The original image must be the resolved source's actual image. Providers
-- overriding picFor with other frames/art never inherit a vanilla mask.
function Cutouts.image(original, path, species)
  if not original or not path or not speciesWithRules[species] then return original end
  local key = tostring(path) .. "#" .. species
  local entries = cache[original]
  if entries and entries[key] ~= nil then return entries[key] or original end
  entries = entries or {}
  cache[original] = entries
  local ok, repaired = pcall(function()
    if Assets.image(path) ~= original then return nil end
    local data = Cutouts.repairData(Assets.imageData(path), species)
    if not data then return nil end
    local image = love.graphics.newImage(data)
    if original.getFilter and image.setFilter then
      image:setFilter(original:getFilter())
    else image:setFilter("nearest", "nearest") end
    return image
  end)
  entries[key] = ok and repaired or false
  return entries[key] or original
end

local function pathFor(pokemon, species, letter)
  local def = pokemon and pokemon[species]
  local path = def and def.spriteFront
  if species == "UNOWN" and letter and letter ~= 0 then
    path = require("src.core.gen2.Unown").formSprite(pokemon, letter, false) or path
  end
  return path
end

-- Attach only to the Modern PC's private native picture renderer. No global
-- engine method is patched and a disabled suite component still builds native.
function Cutouts.attachBox(renderer)
  if not renderer or type(renderer.picFor) ~= "function" then return end
  local native = renderer.picFor
  renderer.picFor = function(self, mon)
    local original = native(self, mon)
    if not mon or mon.isEgg then return original end
    local letter = mon.species == "UNOWN"
      and require("src.core.gen2.Unown").monLetter(mon) or nil
    return Cutouts.image(original, pathFor(self.pokemon, mon.species, letter), mon.species)
  end
end

-- All Modern Dex list/entry/family pictures resolve through this instance.
-- The native Unown tool reads picCache directly, so prepare that one local
-- cache entry as well, retaining first-seen form and per-letter selection.
function Cutouts.attachPokedex(menu)
  if not menu then return end
  local native = menu.picFor
  if type(native) == "function" then
    menu.picFor = function(self, species)
      local original = native(self, species)
      local first = self.save and tonumber(self.save.firstUnownSeen) or 0
      return Cutouts.image(original, pathFor(self.pokemon, species, first), species)
    end
  end
  local nativeUnown = menu.drawUnownPic
  if type(nativeUnown) == "function" then
    menu.drawUnownPic = function(self, letter, ...)
      local path = pathFor(self.pokemon, "UNOWN", letter)
      if path and self.picCache then
        local ok, original = pcall(Assets.image, path)
        if ok then self.picCache[path] = Cutouts.image(original, path, "UNOWN") end
      end
      return nativeUnown(self, letter, ...)
    end
  end
end

return Cutouts
